def dot(v, w):
    return sum(a * b for a, b in zip(v, w))

def project(v, w):
    ww = dot(w, w)
    if ww == 0:
        raise ValueError("cannot project onto the zero vector")
    k = dot(v, w) / ww
    return [k * x for x in w]

