def dot(v, w):
    return sum(a * b for a, b in zip(v, w))

def project(v, w):
    k = dot(v, w) / dot(w, w)
    return [k * x for x in w]

def split(v, w):
    along = project(v, w)
    leftover = [a - b for a, b in zip(v, along)]
    return along, leftover

import numpy as np

def scores(q, K):
    return K @ q

def best(q, K):
    return int(np.argmax(scores(q, K)))
